import 'server-only';
import fs from 'node:fs/promises';
import path from 'node:path';
import { and, eq, inArray } from 'drizzle-orm';
import { db, schema } from '@/server/db';
import { UPLOADS_DIR } from '@/server/env';
import { ALLOWED_TYPES, MAX_FILE_BYTES, isPreviewableImage } from '@/lib/files';

const { files, attachments } = schema;

export function absolutePath(relative: string) {
    const full = path.resolve(/*turbopackIgnore: true*/ UPLOADS_DIR, relative);
    // Stored paths are generated by us, but never let one escape the uploads folder.
    if (!full.startsWith(UPLOADS_DIR + path.sep)) throw new Error('Invalid file path');
    return full;
}

export function checkUpload(file: File): string | null {
    if (!file.size) return `${file.name} is empty`;
    if (file.size > MAX_FILE_BYTES) return `${file.name} is larger than 25 MB`;
    if (!ALLOWED_TYPES[file.type]) return `${file.name}: this file type isn’t supported`;
    return null;
}

/** Writes an upload to disk under a random name and links it to an entity. */
export async function storeAttachment(userId: string, entityType: string, entityId: string, file: File) {
    const id = crypto.randomUUID();
    const month = new Date().toISOString().slice(0, 7);
    const relative = path.join(/*turbopackIgnore: true*/ month, `${id}.${ALLOWED_TYPES[file.type]}`);
    const full = absolutePath(relative);
    await fs.mkdir(path.dirname(full), { recursive: true });
    await fs.writeFile(full, Buffer.from(await file.arrayBuffer()), { mode: 0o600 });

    try {
        db.transaction((tx) => {
            tx.insert(files)
                .values({ id, userId, name: file.name.slice(0, 255) || 'file', mimeType: file.type, size: file.size, path: relative })
                .run();
            tx.insert(attachments).values({ fileId: id, entityType, entityId }).run();
        });
    } catch (error) {
        await fs.rm(full, { force: true });
        throw error;
    }
}

export function listAttachments(userId: string, entityType: string, entityId: string) {
    return db
        .select({ attachmentId: attachments.id, id: files.id, name: files.name, mimeType: files.mimeType, size: files.size, createdAt: files.createdAt })
        .from(attachments)
        .innerJoin(files, eq(files.id, attachments.fileId))
        .where(and(eq(files.userId, userId), eq(attachments.entityType, entityType), eq(attachments.entityId, entityId)))
        .orderBy(attachments.createdAt)
        .all();
}

export type AttachmentRow = ReturnType<typeof listAttachments>[number];

/** First previewable image per entity, used as a card cover. */
export function coverImages(userId: string, entityType: string, entityIds: string[]) {
    if (!entityIds.length) return new Map<string, string>();
    const rows = db
        .select({ entityId: attachments.entityId, fileId: files.id, mimeType: files.mimeType })
        .from(attachments)
        .innerJoin(files, eq(files.id, attachments.fileId))
        .where(and(eq(files.userId, userId), eq(attachments.entityType, entityType), inArray(attachments.entityId, entityIds)))
        .orderBy(attachments.createdAt)
        .all();
    const covers = new Map<string, string>();
    for (const r of rows) if (isPreviewableImage(r.mimeType) && !covers.has(r.entityId)) covers.set(r.entityId, r.fileId);
    return covers;
}

/** Removes files (rows and disk) by id. */
export async function deleteFiles(userId: string, fileIds: string[]) {
    if (!fileIds.length) return;
    const rows = db.select().from(files).where(and(eq(files.userId, userId), inArray(files.id, fileIds))).all();
    db.delete(files).where(and(eq(files.userId, userId), inArray(files.id, fileIds))).run();
    await Promise.all(rows.map((r) => fs.rm(absolutePath(r.path), { force: true })));
}

/** Removes every file attached to an entity (used when the entity is deleted). */
export async function deleteEntityFiles(userId: string, entityType: string, entityIds: string[]) {
    if (!entityIds.length) return;
    const rows = db
        .select({ fileId: attachments.fileId })
        .from(attachments)
        .innerJoin(files, eq(files.id, attachments.fileId))
        .where(and(eq(files.userId, userId), eq(attachments.entityType, entityType), inArray(attachments.entityId, entityIds)))
        .all();
    await deleteFiles(userId, rows.map((r) => r.fileId));
}
